TRANSFORMS={'AGENTS.md': [(3486, 3486, '\n## Live update contract (supersedes the former production-publication paragraph)\n\nThe user sends YouTube URLs to ChatGPT, NOT to an AI generation server in this app. Read the actual current `/engine-spec.json`, save its digest/snapshot, write the Korean book, and register only authorized content. Keep private user notes/keys out of this public repository. No Gemini/OpenAI paid generation API is added by this migration.\n\nOrdinary changes to books, chapters, reader UI, CSS, JS and the current authoring rules go through `.github/workflows/chatbook-live-publish.yml`. It builds, tests in Chromium, writes immutable `live/assets`/`live/release.json`, then atomically advances `live/channel.json`. It NEVER calls Netlify. The existing Netlify URL uses a fixed same-origin gateway. Do not revive legacy production helpers or archived workflows.\n\n`netlify/**`, `netlify.toml`, `public/live-guard.js`, `public/live-sw.js`, and the PWA identity are the frozen bootstrap contract. A necessary security/server/loader update needs a separately approved and tested bootstrap deployment, not a routine live publish. The user approved one initial migration deployment; that does not authorize further production deployments.\n\nThe live gateway permits only fixed-repository manifest-listed assets, verifies size/SHA-256, retains CSP self-only scripts, pins one complete version, and preserves the same origin and sync endpoints. The guard defers record writes during startup, and a broken startup falls back to a prior known-good/bundled reader. Offline caching advances only after every asset is verified. First offline use requires one successful online preparation; actual Galaxy behavior is not implied by Chromium tests.\n\nNever silently remove existing book/chapter/block IDs. For explicitly requested structural removals, document retired anchors in `live/retired-anchors.json`; keep user annotation records untouched. A hash and structural test cannot prove video access, accurate translation, or semantic completeness. Common policy edits remain separate from book-only edits.\n')], 'netlify.toml': [(1563, 1563, '\n# Fixed same-origin live gateway: bundled emergency copy, not a new deploy per book.\n[functions."live"]\n  included_files = ["dist/**"]\n')], 'package.json': [(365, 365, 'check public/live-guard.js && node --check public/live-sw.js && node --'), (384, 384, '.test.mjs tests/live/gateway')], 'public/core.js': [(5662, 5662, 'if(window.ChatbookLive?.pending)return;'), (13130, 13131, ''), (14007, 14007, 'if(window.ChatbookLive?.pending)return false;'), (15220, 15342, ''), (15387, 15408, 'h'), (15410, 15410, 'bookL'), (15411, 15411, 've)return wind'), (15412, 15412, 'w.ChatbookLive.check(ma'), (15413, 15421, 'ua'), (15422, 15432, ''), (15433, 15434, ';'), (15455, 15459, '저장본'), (15461, 15463, '검증'), (15465, 15467, '기본'), (15468, 15471, '교재입'), (15474, 15479, ''), (15489, 15493, '새'), (15494, 15496, '버전을 확인해 주세'), (15506, 16599, '')], 'public/app.js': [(521, 521, 'if(window.ChatbookLive)return window.ChatbookLive.saveOffline();'), (13058, 13116, ''), (13590, 13591, ''), (13592, 13592, 'live-'), (13598, 13598, ",{scope:'/'}"), (14135, 14135, ".then(()=>window.ChatbookLive?.ready()).catch(error=>{if(window.ChatbookLive)window.ChatbookLive.fail('init');else console.error(error);})")], 'scripts/build.mjs': [(3123, 3123, "\n// Frozen emergency package for the fixed live gateway; never part of the moving live asset map.\nconst {makeManifest}=await import('./live-package.mjs');\nfs.writeFileSync(path.join(root,'dist/bootstrap-manifest.json'),JSON.stringify(makeManifest(path.join(root,'dist'),{sequence:1,sourceSha}),null,2)+'\\n');\n")], 'scripts/fast-publish.mjs': [(0, 0, "throw new Error('Production publishing is disabled. Use chatbook-live-publish: books/UI/spec update without a Netlify deploy.');\n")], 'scripts/ci-deploy.mjs': [(0, 0, "throw new Error('Legacy production pipeline disabled after live-update migration.');\n")]}
ARCHIVE=['.github/workflows/chatbook-ci.yml', '.github/workflows/chatbook-engine-install.yml', '.github/workflows/chatbook-fast-publish.yml', '.github/workflows/chatbook-learning-1.1.yml', '.github/workflows/chatbook-narrative-upgrade.yml', '.github/workflows/chatbook-upgrade-audit.yml', '.github/workflows/frames-8KCuHHeC_M0-once.yml', '.github/workflows/import-0SGfDKMLdaI-once.yml', '.github/workflows/import-8KCuHHeC_M0-once.yml']
for name,want in EXPECTED_BEFORE.items():
    assert hashlib.sha256((root/name).read_bytes()).hexdigest()==want, 'Baseline changed; stop: '+name
parts=[root/('scripts/live-migration-data-'+str(i)+'.b64') for i in range(4)]
raw=gzip.decompress(base64.b64decode(''.join(p.read_text().strip() for p in parts),validate=True))
assert hashlib.sha256(raw).hexdigest()=='80fce59fc2e17c12adef1f6932e2a944344a1fa9c8548cec24e662a17b8e1f6a','Source transport integrity mismatch'
new=json.loads(raw)
assert len(new)==13
for name in new:
    assert '..' not in name and not name.startswith('/') and name.startswith(('netlify/','public/','scripts/','tests/live/','.github/workflows/'))
    assert not (root/name).exists(), 'New file already exists: '+name
changes={}
for name,operations in TRANSFORMS.items():
    text=(root/name).read_text()
    for i,j,replacement in reversed(operations): text=text[:i]+replacement+text[j:]
    assert hashlib.sha256(text.encode()).hexdigest()==EXPECTED_AFTER[name], 'Unexpected patch result: '+name
    changes[name]=text
for name,text in {**new,**changes}.items():
    dest=root/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text)
for name in ARCHIVE:
    source=root/name;dest=root/'docs/disabled-workflows'/(source.name+'.txt')
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(source.read_bytes());source.unlink()
for p in parts:p.unlink()
pathlib.Path(__file__).unlink()
print('Installed 13 audited modules and',len(changes),'scoped edits; preserved books/policy/sync; no deployment performed.')
